impl ModelAdapter for Fixture {
    fn complete<'a>(
        &'a self,
        messages: &'a [Message],
        _: &'a [ToolDefinition],
    ) -> Pin<Box<dyn Future<Output = Result<ModelTurn, ToolError>> + Send + 'a>> {
        let n = self.calls.fetch_add(1, Ordering::SeqCst) + 1;
        let path = self.path.clone();
        let has_tool = messages.iter().any(|m| m.role == "tool");
        let tool_content = messages
            .iter()
            .find(|m| m.role == "tool" && m.tool_call_id.as_deref() == Some("model-call"))
            .map(|m| m.content.clone());
        Box::pin(async move {
            if n == 1 {
                let call = ToolCall {
                    id: "model-call".into(),
                    name: "read_file".into(),
                    arguments: serde_json::json!({"path":path}),
                };
                return Ok(ModelTurn {
                    message: Message {
                        role: "assistant".into(),
                        content: String::new(),
                        tool_call_id: None,
                        tool_calls: vec![call.clone()],
                    },
                    tool_calls: vec![call],
                });
            }
            Ok(ModelTurn {
                message: Message {
                    role: "assistant".into(),
                    content: if has_tool && tool_content.as_deref() == Some("fixture-output\n") {
                        tool_content.unwrap()
                    } else {
                        String::new()
                    },
                    tool_call_id: None,
                    tool_calls: vec![],
                },
                tool_calls: vec![],
            })
        })
    }
}
