async fn cancellation_wait_is_observed_after_started() {
    let signal = ControlSignal::new();
    let (result, calls, _, _) = tokio::time::timeout(
        std::time::Duration::from_secs(8),
        run(Some("cancellation_wait"), signal.clone()),
    )
